<template><ion-page><ion-content><main class="teacher"><header><button @click="router.push('/choice')">Exit</button><p>MANUSH-E / TEACHER</p></header><h1>Your learning groups</h1><p v-if="loading">Loading classroom...</p><section v-for="group in groups" :key="group.id"><p>{{ group.school_name }}</p><h2>{{ group.name }}</h2><article v-for="student in group.students" :key="student.id"><span>{{ student.name }}</span><small>{{ student.completed_activities }}/{{ student.total_activities }} packs complete</small></article></section></main></ion-content></ion-page></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{IonContent,IonPage}from'@ionic/vue';import{useRouter}from'vue-router';import axios from'axios';const router=useRouter(),groups=ref<any[]>([]),loading=ref(true);onMounted(async()=>{try{const token=import.meta.env.MODE==='development'&&import.meta.env.VITE_TEST_TEACHER_API_TOKEN?import.meta.env.VITE_TEST_TEACHER_API_TOKEN:localStorage.getItem('api_token');const r=await axios.get(`${import.meta.env.VITE_API_ENDPOINT}/portal/teacher`,{headers:{Authorization:`Bearer ${token}`}});groups.value=r.data.data;}finally{loading.value=false;}});</script>
<style scoped>.teacher{background:#132541;color:#f7f2e6;min-height:100%;padding:25px max(22px,calc((100vw - 920px)/2))}header{display:flex;justify-content:space-between}button{background:transparent;border:0;color:inherit}h1,h2{font-family:Georgia,serif;font-weight:400}h1{font-size:clamp(3rem,9vw,5rem)}section{background:#f7f2e6;border-radius:22px;color:#18342f;margin:18px 0;padding:22px}section>p{color:#698078;font-size:.8rem}article{border-top:1px solid #ddd5c4;display:flex;justify-content:space-between;padding:15px 0}small{color:#587066}</style>
